sys_script_include.script:
var MedicationService = Class.create();

MedicationService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Medication record exists.
     *
     * @param {String} medicationSysId
     * @return {Boolean}
     */
    medicationExists: function(medicationSysId) {

        if (this.validationUtils.isEmpty(medicationSysId)) {
            return false;
        }

        var medication = new GlideRecord(
            'x_2130921_caresy_0_medication'
        );

        if (!medication.isValid()) {
            gs.error(
                'MedicationService: Medication table is invalid.'
            );
            return false;
        }

        return medication.get(medicationSysId);
    },

    /**
     * Retrieve a Medication record.
     *
     * @param {String} medicationSysId
     * @return {GlideRecord|null}
     */
    getMedication: function(medicationSysId) {

        if (this.validationUtils.isEmpty(medicationSysId)) {
            return null;
        }

        var medication = new GlideRecord(
            'x_2130921_caresy_0_medication'
        );

        if (!medication.isValid()) {
            gs.error(
                'MedicationService: Medication table is invalid.'
            );
            return null;
        }

        if (medication.get(medicationSysId)) {
            return medication;
        }

        return null;
    },

    /**
     * Check whether a Medication is currently active.
     *
     * Medication Status:
     * Prescribed
     * Active
     * Held
     * Completed
     * Discontinued
     *
     * @param {String} medicationSysId
     * @return {Boolean}
     */
    isMedicationActive: function(medicationSysId) {

        var medication = this.getMedication(medicationSysId);

        if (!medication) {
            return false;
        }

        return medication.getValue('medication_status') == 'Active';
    },

    type: 'MedicationService'
};
